parameters.functionCode:
const pipeline = $node['Get Pipeline Summary'].json;
const winLoss = $node['Get Win/Loss Data'].json;
const repPerf = $node['Get Rep Performance'].json;

const pipelineData = Array.isArray(pipeline) ? pipeline : (pipeline?.stage ? [pipeline] : []);
const reps = Array.isArray(repPerf) ? repPerf : (repPerf?.assigned_to ? [repPerf] : []);

// Pipeline totals
const totalPipeline = pipelineData.reduce((sum, s) => sum + (parseFloat(s.total_value) || 0), 0);
const weightedForecast = pipelineData.reduce((sum, s) => sum + (parseFloat(s.weighted_value) || 0), 0);
const totalDeals = pipelineData.reduce((sum, s) => sum + (parseInt(s.deal_count) || 0), 0);

// Win/loss
const wonCount = parseInt(winLoss?.won_count) || 0;
const wonValue = parseFloat(winLoss?.won_value) || 0;
const lostCount = parseInt(winLoss?.lost_count) || 0;
const winRate = (wonCount + lostCount) > 0 ? Math.round(wonCount / (wonCount + lostCount) * 100) : 0;
const avgCycle = Math.round(parseFloat(winLoss?.avg_cycle_days) || 0);

// Forecast: weighted pipeline + historical win rate adjustment
const adjustedForecast = weightedForecast * (winRate / 100 || 0.3);

// Monthly target (configurable)
const monthlyTarget = parseFloat($env.MONTHLY_REVENUE_TARGET) || 500000000; // 500M IDR default
const targetProgress = wonValue / monthlyTarget * 100;

return [{
  json: {
    period: new Date().toLocaleString('id-ID', { month: 'long', year: 'numeric' }),
    pipeline: {
      total_deals: totalDeals,
      total_value: totalPipeline,
      weighted_forecast: weightedForecast,
      by_stage: pipelineData.map(s => ({
        stage: s.stage,
        deals: parseInt(s.deal_count),
        value: parseFloat(s.total_value),
        avg_probability: Math.round(parseFloat(s.avg_probability))
      }))
    },
    performance: {
      won_this_month: wonCount,
      won_value: wonValue,
      lost_this_month: lostCount,
      win_rate: winRate,
      avg_sales_cycle_days: avgCycle
    },
    forecast: {
      weighted_pipeline: weightedForecast,
      adjusted_forecast: adjustedForecast,
      monthly_target: monthlyTarget,
      target_progress_percent: Math.round(targetProgress),
      gap_to_target: Math.max(0, monthlyTarget - wonValue)
    },
    reps: reps.map(r => ({
      name: r.assigned_to,
      deals: parseInt(r.deal_count),
      value: parseFloat(r.total_value),
      won: parseInt(r.won),
      lost: parseInt(r.lost)
    }))
  }
}];

